const data = $input.first().json;

// Format phone: ensure it starts with country code
let phone = (data.phone || '').replace(/\s+/g, '').replace(/^0+/, '');
if (!phone.startsWith('+')) {
  // Default to Egypt +20 if no country code
  phone = phone.startsWith('20') ? `+${phone}` : `+20${phone}`;
}

// Build bilingual message
const name = data.name || 'عزيزي العميل';
const country = data.country || '';
const budget = data.budget ? `$${Number(data.budget).toLocaleString()}` : '';

const message = `مرحباً ${name}! 🏠

شكراً لاهتمامك بعقاراتنا في مصر.
سيتواصل معك فريقنا قريباً لمساعدتك في إيجاد العقار المناسب.

---
Hello ${name}! 🏠

Thank you for your interest in Egyptian real estate.
Our team will contact you shortly to help find the perfect property${budget ? ` within your budget of ${budget}` : ''}.

Leads Egypt | ${new Date().getFullYear()}`;

return [{ json: { phone, message, name, leadId: data.leadId } }];
